-- ===BATCH=== V8 schema-split-collect-config
/* V8: split public into collect/config (Darling security hardening, #1262).
   Table NAMES are unchanged; search_path = collect, config, public resolves the bare
   references every SQL site already uses, so no query is re-qualified. */

CREATE SCHEMA IF NOT EXISTS collect AUTHORIZATION darling;
CREATE SCHEMA IF NOT EXISTS config AUTHORIZATION darling;

/* collect: all collector tables (from the catalog) + registry/metadata + the V4-V6 views */
ALTER TABLE IF EXISTS public.wait_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.latch_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.spinlock_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.cpu_scheduler_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.plan_cache_stats SET SCHEMA collect;
ALTER TABLE IF EXISTS public.tempdb_stats SET SCHEMA collect;
