-- ===BATCH=== V38 query-payload-dimensions
/* V38: hash-keyed dimension tables for query_stats / procedure_stats payloads (#1767).
   query_text/query_plan_xml stored inline per row were 94% of a 250 GB field store;
   a measured 1-hour window held 3,166 MB of payload across 23 MB of distinct content.
   ZERO-REWRITE: the inline columns stay, new rows leave them NULL, readers coalesce,
   and raw retention ages the inline copies out on its own. */

CREATE TABLE IF NOT EXISTS query_text_dim (
    digest bytea NOT NULL PRIMARY KEY,
    query_text text NOT NULL,
    last_seen timestamp NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_query_text_dim_last_seen ON query_text_dim(last_seen);

CREATE TABLE IF NOT EXISTS query_plan_dim (
    digest bytea NOT NULL PRIMARY KEY,
    query_plan_xml text NULL,
    query_plan_gz bytea NULL,
    last_seen timestamp NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_query_plan_dim_last_seen ON query_plan_dim(last_seen);

ALTER TABLE query_stats ADD COLUMN IF NOT EXISTS query_text_digest bytea;
ALTER TABLE query_stats ADD COLUMN IF NOT EXISTS query_plan_digest bytea;
ALTER TABLE procedure_stats ADD COLUMN IF NOT EXISTS query_plan_digest bytea;
