ALTER TABLE query_stats ADD COLUMN IF NOT EXISTS total_spills bigint;
ALTER TABLE query_stats ADD COLUMN IF NOT EXISTS min_worker_time bigint;
ALTER TABLE query_stats ADD COLUMN IF NOT EXISTS max_worker_time bigint;
ALTER TABLE query_stats ADD COLUMN IF NOT EXISTS min_elapsed_time bigint;
