-- ===BATCH=== V47 pvs-stats

CREATE TABLE IF NOT EXISTS collect.pvs_stats (
    collection_id bigint NOT NULL,
    collection_time timestamp NOT NULL,
    server_id integer NOT NULL,
    server_name text NOT NULL,
    database_name text,
    database_id integer,
