-- ===BATCH=== V51 query-stats-host-object

ALTER TABLE query_stats
    ADD COLUMN IF NOT EXISTS host_object_name text;
DROP VIEW IF EXISTS v_query_stats;

ALTER TABLE query_plan_dim
    ADD COLUMN IF NOT EXISTS query_plan_gz bytea;
ALTER TABLE query_plan_dim
    ALTER COLUMN query_plan_xml DROP NOT NULL;
/* v_query_stats resolves each row's payload: the inline column for rows written before
   the dimension tables existed, the dimension row for every row written since (#1767).
   Column list generated from the collector definition so it can never go stale. */
CREATE OR REPLACE VIEW v_query_stats AS
SELECT
    f.collection_id,
    f.collection_time,
    f.server_id,
    f.server_name,
    f.database_name,
    f.query_hash,
    f.query_plan_hash,
    f.creation_time,
    f.last_execution_time,
    f.execution_count,
    f.total_worker_time,
    f.total_elapsed_time,
    f.total_logical_reads,
    f.total_logical_writes,
    f.total_physical_reads,
    f.total_clr_time,
    f.total_rows,
    f.total_spills,
    f.min_worker_time,
    f.max_worker_time,
    f.min_elapsed_time,
    f.max_elapsed_time,
    f.min_physical_reads,
    f.max_physical_reads,
    f.min_rows,
    f.max_rows,
    f.min_dop,
    f.max_dop,
    f.min_grant_kb,
    f.max_grant_kb,
    f.min_used_grant_kb,
    f.max_used_grant_kb,
    f.min_ideal_grant_kb,
    f.max_ideal_grant_kb,
    f.min_reserved_threads,
    f.max_reserved_threads,
    f.min_used_threads,
    f.max_used_threads,
    f.min_spills,
    f.max_spills,
    COALESCE(f.query_text, qtd.query_text) AS query_text,
    COALESCE(f.query_plan_xml, qpd.query_plan_xml) AS query_plan_xml,
    f.sql_handle,
    f.plan_handle,
    f.delta_execution_count,
    f.delta_worker_time,
    f.delta_elapsed_time,
    f.delta_logical_reads,
    f.delta_logical_writes,
    f.delta_physical_reads,
    f.delta_rows,
    f.delta_spills,
    f.plan_generation_num,
    f.sample_interval_seconds,
    f.host_object_name,
    f.query_text_digest,
    f.query_plan_digest,
    qpd.query_plan_gz
FROM query_stats AS f
LEFT JOIN query_text_dim AS qtd ON qtd.digest = f.query_text_digest
LEFT JOIN query_plan_dim AS qpd ON qpd.digest = f.query_plan_digest
;
INSERT INTO darling_schema_version (version, name, applied_at) VALUES (51, 'query-stats-host-object', now()::timestamp);
